/* ============ CarbonForge 内核 ============
   轻量语法高亮 tokenizer + SVG 渲染，全部纯函数、零依赖。 */
var CarbonForgePure = (function(){
  var KW = {
    js:['const','let','var','function','return','if','else','for','while','class','new','await','async','import','export','from','default','try','catch','throw','typeof','of','in','this','null','undefined','true','false','switch','case','break','continue','do','yield','static','extends','super','delete','void','interface','type','enum','implements','public','private','readonly','number','string','boolean','any','as'],
    py:['def','return','if','elif','else','for','while','import','from','as','class','try','except','finally','with','lambda','None','True','False','and','or','not','in','is','pass','break','continue','raise','yield','global','nonlocal','assert','del','async','await'],
    bash:['if','then','else','elif','fi','for','while','do','done','case','esac','function','echo','export','local','return','in','select','until','sudo'],
    json:['true','false','null'],
    html:['div','span','a','img','html','head','body','script','style','link','meta','input','button','p','ul','li','table','tr','td','h1','h2','h3','title']
  };

  function tokenize(code, lang){
    lang = lang || 'js';
    var kws = KW[lang] || KW.js; var set = {}; kws.forEach(function(k){ set[k]=1; });
    var re, m, toks=[], i;
    if(lang==='json'){
      re = /("(?:\\.|[^"\\])*")|(-?\d+\.?\d*(?:[eE][+-]?\d+)?)|\b(true|false|null)\b|([{}\[\],:])|(\s+)/g;
      while((m=re.exec(code))){
        if(m[1]!=null) toks.push({t:'string', v:m[1]});
        else if(m[2]!=null) toks.push({t:'number', v:m[2]});
        else if(m[3]!=null) toks.push({t:'keyword', v:m[3]});
        else if(m[4]!=null) toks.push({t:'punct', v:m[4]});
        else toks.push({t:'ws', v:m[5]});
      }
    } else {
      re = /(\/\/[^\n]*|\/\*[\s\S]*?\*\/|#[^\n]*)|("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`)|\b(0x[0-9a-fA-F]+|\d+\.?\d*(?:[eE][+-]?\d+)?)\b|([A-Za-z_$][\w$]*)|(\s+)|([^\sA-Za-z0-9_$])/g;
      while((m=re.exec(code))){
        if(m[1]!=null) toks.push({t:'comment', v:m[1]});
        else if(m[2]!=null) toks.push({t:'string', v:m[2]});
        else if(m[3]!=null) toks.push({t:'number', v:m[3]});
        else if(m[4]!=null) toks.push({t:(set[m[4]]?'keyword':'ident'), v:m[4]});
        else if(m[5]!=null) toks.push({t:'ws', v:m[5]});
        else toks.push({t:'punct', v:m[6]});
      }
    }
    // JSON key 识别：字符串后紧跟冒号
    if(lang==='json'){
      for(i=0;i<toks.length;i++){
        if(toks[i].t==='string'){
          var j=i+1; while(j<toks.length && toks[j].t==='ws') j++;
          if(j<toks.length && toks[j].t==='punct' && toks[j].v===':') toks[i].t='key';
        }
      }
    }
    return toks;
  }

  var THEMES = {
    dark:{bg:'#0A0A0B', fg:'#F8F8F2', comment:'#6272A4', string:'#50FA7B', number:'#BD93F9', keyword:'#FF79C6', key:'#8BE9FD', ident:'#F8F8F2', punct:'#FF79C6'},
    light:{bg:'#FFFFFF', fg:'#383A42', comment:'#A0A1A7', string:'#50A14E', number:'#986801', keyword:'#A626A4', key:'#4078F2', ident:'#383A42', punct:'#383A42'}
  };

  function esc(s){ return String(s).replace(/[&<>]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;'}[c]; }); }

  function renderSvg(code, lang, opts){
    opts = opts || {};
    var theme = THEMES[opts.theme] || THEMES.dark;
    var bg = opts.bg || theme.bg;
    var font = opts.font || 15;
    var pad = opts.pad || 40;
    var lh = Math.round(font*1.6);
    var chromH = 44;
    var lines = String(code).split('\n');
    var cw = font*0.6;
    var maxLen = 1;
    lines.forEach(function(l){ if(l.length>maxLen) maxLen=l.length; });
    var W = Math.ceil(pad*2 + maxLen*cw + 16);
    var H = chromH + pad + lines.length*lh + pad - (lh-font);
    var parts = ['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '+W+' '+H+'" width="'+W+'" height="'+H+'">'];
    parts.push('<rect width="'+W+'" height="'+H+'" rx="12" fill="'+bg+'"/>');
    parts.push('<circle cx="'+(pad)+'" cy="'+(chromH/2)+'" r="6" fill="#ff5f56"/>');
    parts.push('<circle cx="'+(pad+22)+'" cy="'+(chromH/2)+'" r="6" fill="#ffbd2e"/>');
    parts.push('<circle cx="'+(pad+44)+'" cy="'+(chromH/2)+'" r="6" fill="#27c93f"/>');
    parts.push('<text x="'+pad+'" y="'+(chromH+pad-6)+'" font-family="ui-monospace,SFMono-Regular,Menlo,Consolas,monospace" font-size="'+font+'" xml:space="preserve">');
    var y = chromH + pad - 6;
    lines.forEach(function(line, li){
      var toks = tokenize(line, lang);
      var inner = toks.map(function(tk){
        if(tk.t==='ws') return esc(tk.v);
        var col = theme[tk.t] || theme.fg;
        return '<tspan fill="'+col+'">'+esc(tk.v)+'</tspan>';
      }).join('');
      parts.push('<tspan x="'+pad+'" dy="'+(li===0?0:lh)+'">'+inner+'</tspan>');
    });
    parts.push('</text></svg>');
    return parts.join('');
  }

  return { tokenize:tokenize, renderSvg:renderSvg, THEMES:THEMES };
})();
if (typeof module !== 'undefined' && module.exports) module.exports = CarbonForgePure;
if (typeof window !== 'undefined') window.CarbonForgePure = CarbonForgePure;
